            String[] n = s[0].split("\\.\\.");
            switch(n.length) {
                case 2:
                    bs.set(Integer.parseUnsignedInt(n[0], 16), 1 + Integer.parseUnsignedInt(n[1], 16));
                    break;
                case 1:
                    bs.set(Integer.parseUnsignedInt(n[0], 16));
                    break;
